using UnityEngine;
using UnityEditor;
using System;
using System.IO;
using ConRoi.Investigation.V36;
using Object = UnityEngine.Object;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            s.SaveDirectoryOverride = Path.GetFullPath("Test/KetQua/investigation_r102/route-profile");
            if (!s.Load())
                throw new Exception(s.Message);
            s.SaveDirectoryOverride = Path.GetFullPath("Test/KetQua/investigation_r102/final-ui-profile");
            s.OpenPage("cipher");
            ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r102/cipher-final-empty.png");
            r.Log("Loaded own verified route profile, lifecycle fixture separate from controller evidence. Cipher empty=" + (s.data.mapping.Count == 0) + " p=" + s.movement.transform.position);
        }
    }
}

